from __future__ import absolute_import
from selenium.webdriver.common.by import By
from taf.selenium.sbts.pages import v26r1


class SbtsLoginPage(v26r1.SbtsLoginPage):

    def _configure_port_and_ssl(self, port, ssl):
        self.click_and_wait_for_corresponding_element_visible(self._OPTIONS_BUTTON_XPATH,
                                                              self._PORT_LABEL_XPATH)

        if self.element_exists((By.XPATH, self._SSL_CHECKBOX_XPATH), timeout=2):
            self.select_checkbox_by_specified_status(ssl, self._SSL_CHECKBOX_XPATH, self._SSL_CHECKBOX_XPATH)

        self.insert_text_to_enable_element((By.XPATH, self._PORT_INPUT_XPATH), port)
